using HakutaiKagami.Core.Contracts;
using Xunit;
using System.Reflection;
namespace HakutaiKagami.Tests;
public sealed class PreparedSubmitTests
{
    static string Hash(WorldSession s)=>ContractJson.CanonicalHash(s.DiagnosticSnapshot());
    static WorldSession Source(){var s=new WorldSession(ContractFixture.Create());s.SetPaused(true);return s;}
    [Theory][InlineData(ActionKind.Inspect,false)][InlineData(ActionKind.Inspect,true)][InlineData(ActionKind.Move,false)][InlineData(ActionKind.Move,true)][InlineData(ActionKind.Transfer,false)][InlineData(ActionKind.Transfer,true)]
    public async Task PrivatePreparationEqualsExistingSubmitExactly(ActionKind action,bool unpause)
    {
        var source=Source();string before=Hash(source);var input=ContractFixture.Order("request:prepared-submit",action,action==ActionKind.Transfer?17:0);var expected=new WorldSession(source.DiagnosticSnapshot());var result=expected.Submit(input,expected.Revision);Assert.Equal(ResultCode.Accepted,result.Code);if(unpause)expected.SetPaused(false);
        var ready=await source.CaptureSubmit(input,source.Revision,unpause).PrepareAsync();Assert.Equal(before,Hash(source));var host=new WorldSessionHost(source);Assert.Equal(ResultCode.Accepted,host.CommitSubmit(ready,out var publication));Assert.Equal(result,publication!.Result);Assert.Equal(Hash(expected),Hash(host.Current));Assert.Equal(Hash(expected),ContractJson.CanonicalHash(publication.Display));
        string committed=Hash(host.Current);publication.Display.IdCounters.Clear();publication.Display.Paused=!publication.Display.Paused;Assert.Equal(committed,Hash(host.Current));Assert.Equal(ResultCode.StateChanged,host.CommitSubmit(ready,out var twice));Assert.Null(twice);Assert.Equal(before,Hash(source));
    }
    [Fact]public void CaptureAndPreparedPublicSurfaceContainNoFutureWorldOrResult()
    {
        var source=Source();var capture=source.CaptureSubmit(ContractFixture.Order("request:opaque"),source.Revision);var ready=capture.Prepare();
        Assert.All(capture.GetType().GetProperties(BindingFlags.Instance|BindingFlags.Public),p=>Assert.Equal(typeof(long),p.PropertyType));Assert.Empty(ready.GetType().GetProperties(BindingFlags.Instance|BindingFlags.Public));Assert.Empty(ready.GetType().GetFields(BindingFlags.Instance|BindingFlags.Public));
    }
    [Fact]public void CapturedIntentRemainsASealedImmutableValueGraph()
    {
        bool Value(Type t){var x=Nullable.GetUnderlyingType(t)??t;return x.IsEnum||x==typeof(string)||x==typeof(long)||x==typeof(int)||x==typeof(bool)||x==typeof(EntityId)||x==typeof(DeadlinePolicy);}
        Assert.True(typeof(Intent).IsSealed&&typeof(DeadlinePolicy).IsSealed);
        foreach(var t in new[]{typeof(Intent),typeof(DeadlinePolicy)})Assert.All(t.GetProperties(BindingFlags.Instance|BindingFlags.Public),p=>{Assert.True(Value(p.PropertyType),p.Name);Assert.True(p.SetMethod==null||p.SetMethod.ReturnParameter.GetRequiredCustomModifiers().Contains(typeof(System.Runtime.CompilerServices.IsExternalInit)),p.Name);});
    }
    [Fact]public void StaleRevisionCannotCapture(){var s=Source();Assert.Throws<InvalidOperationException>(()=>s.CaptureSubmit(ContractFixture.Order("request:stale"),s.Revision+1));}
    [Fact]public void ChangedActualGenerationRejectsPreparedInput(){var s=Source();var ready=s.CaptureSubmit(ContractFixture.Order("request:changed"),s.Revision).Prepare();s.SetPaused(false);string before=Hash(s);var h=new WorldSessionHost(s);Assert.Equal(ResultCode.StateChanged,h.CommitSubmit(ready,out var p));Assert.Null(p);Assert.Equal(before,Hash(h.Current));}
    [Fact]public void EqualBytesInAnotherSessionCannotAccept(){var s=Source();var ready=s.CaptureSubmit(ContractFixture.Order("request:foreign"),s.Revision).Prepare();var h=new WorldSessionHost(new WorldSession(s.DiagnosticSnapshot()));Assert.Equal(ResultCode.StateChanged,h.CommitSubmit(ready,out var p));Assert.Null(p);}
    [Fact]public void CancellationBeforePreparationLeavesSource(){var s=Source();string before=Hash(s);using var stop=new CancellationTokenSource();stop.Cancel();Assert.Throws<OperationCanceledException>(()=>s.CaptureSubmit(ContractFixture.Order("request:cancel-before"),s.Revision).Prepare(stop.Token));Assert.Equal(before,Hash(s));}
    [Fact]public void CancellationAfterPreparationCannotPublish(){var s=Source();string before=Hash(s);using var stop=new CancellationTokenSource();var ready=s.CaptureSubmit(ContractFixture.Order("request:cancel-after"),s.Revision,true).Prepare(stop.Token);stop.Cancel();var h=new WorldSessionHost(s);Assert.Equal(ResultCode.NotAvailable,h.CommitSubmit(ready,out var p));Assert.Null(p);Assert.Equal(before,Hash(h.Current));}
    [Fact]public void FailureAfterPrivateSubmitHasNoPartialEffect(){var s=Source();string before=Hash(s);Assert.Throws<IOException>(()=>s.CaptureSubmit(ContractFixture.Order("request:fault"),s.Revision,true).Prepare(beforePublication:()=>throw new IOException("declared-submit-fault")));Assert.Equal(before,Hash(s));Assert.Empty(s.DiagnosticSnapshot().Requests);}
    [Fact]public void DuplicateUsesExistingIdempotenceWithoutAnotherTask(){var s=Source();var i=ContractFixture.Order("request:duplicate");Assert.Equal(ResultCode.Accepted,s.Submit(i,s.Revision).Code);var expected=new WorldSession(s.DiagnosticSnapshot());var result=expected.Submit(i,expected.Revision);Assert.Equal(ResultCode.AlreadyAccepted,result.Code);expected.SetPaused(false);var ready=s.CaptureSubmit(i,s.Revision,true).Prepare();var h=new WorldSessionHost(s);Assert.Equal(ResultCode.Accepted,h.CommitSubmit(ready,out var p));Assert.Equal(result,p!.Result);Assert.Equal(Hash(expected),Hash(h.Current));Assert.Single(h.Current.DiagnosticSnapshot().Tasks);}
    [Fact]public void PayloadConflictDoesNotUnpause(){var s=Source();var i=ContractFixture.Order("request:conflict");s.Submit(i,s.Revision);string before=Hash(s);var ready=s.CaptureSubmit(i with{WorkSeconds=i.WorkSeconds+1},s.Revision,true).Prepare();var h=new WorldSessionHost(s);Assert.Equal(ResultCode.Accepted,h.CommitSubmit(ready,out var p));Assert.Equal(ResultCode.IdPayloadConflict,p!.Result.Code);Assert.Equal(before,Hash(h.Current));Assert.True(h.Current.Paused);}
    [Fact]public void RejectedAuthorityUsesExistingValidationWithoutUnpause(){var s=Source();var i=ContractFixture.Order("request:forbidden") with{Actor=new EntityId("person:missing")};var expected=new WorldSession(s.DiagnosticSnapshot());var result=expected.Submit(i,expected.Revision);Assert.True(result.Code is not(ResultCode.Accepted or ResultCode.AlreadyAccepted));var ready=s.CaptureSubmit(i,s.Revision,true).Prepare();var h=new WorldSessionHost(s);Assert.Equal(ResultCode.Accepted,h.CommitSubmit(ready,out var p));Assert.Equal(result,p!.Result);Assert.Equal(Hash(expected),Hash(h.Current));Assert.True(h.Current.Paused);}
    [Fact]public void TwoCandidatesCannotOverwriteOneSource(){var s=Source();var first=s.CaptureSubmit(ContractFixture.Order("request:first"),s.Revision).Prepare();var second=s.CaptureSubmit(ContractFixture.Order("request:second"),s.Revision).Prepare();var h=new WorldSessionHost(s);Assert.Equal(ResultCode.Accepted,h.CommitSubmit(first,out _));string before=Hash(h.Current);Assert.Equal(ResultCode.StateChanged,h.CommitSubmit(second,out var p));Assert.Null(p);Assert.Equal(before,Hash(h.Current));Assert.Single(h.Current.DiagnosticSnapshot().Requests);}
    [Fact]public void LoadingSameRevisionRejectsOldCandidate(){var s=Source();var h=new WorldSessionHost(s);var ready=s.CaptureSubmit(ContractFixture.Order("request:load"),s.Revision).Prepare();var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"hakutai-submit-load",Guid.NewGuid().ToString("N")),w.Definitions);store.Save(s,"manual",w.WorldId);Assert.Equal(ResultCode.Accepted,h.CommitLoad(store.Prepare("manual"),s,s.Revision));string before=Hash(h.Current);Assert.Equal(ResultCode.StateChanged,h.CommitSubmit(ready,out _));Assert.Equal(before,Hash(h.Current));}
    [Fact]public async Task RealSourceCanChangeWhileComputedPrivateSubmitIsHeld(){var s=Source();using var entered=new ManualResetEventSlim();using var release=new ManualResetEventSlim();var c=s.CaptureSubmit(ContractFixture.Order("request:held"),s.Revision,true);var job=Task.Run(()=>c.Prepare(beforePublication:()=>{entered.Set();Assert.True(release.Wait(TimeSpan.FromSeconds(10)));}));Assert.True(entered.Wait(TimeSpan.FromSeconds(10)));string retained;try{s.SetPaused(false);retained=Hash(s);Assert.Empty(s.DiagnosticSnapshot().Requests);}finally{release.Set();}var ready=await job;var h=new WorldSessionHost(s);Assert.Equal(ResultCode.StateChanged,h.CommitSubmit(ready,out _));Assert.Equal(retained,Hash(h.Current));}
    [Fact]public async Task ThousandPersonInspectionMatchesCurrentCompactAuthority(){var records=Enumerable.Range(0,1000).Select(i=>NewGameWorldTests.Officer("created:submit-pop-"+i,site:NationalRoutes.Sites[i%NationalRoutes.Sites.Length].Id.Value)).ToArray();var setup=NewGameWorldTests.Setup(records);var s=new WorldSession(NewGameWorld.Create(setup.World,setup.Registered,"person:nobunaga",personalAuthorityLayout:NewGameWorld.CompactPersonalAuthority));var input=NewGameWorld.Inspect(s.DiagnosticSnapshot(),"request:thousand");var expected=new WorldSession(s.DiagnosticSnapshot());var result=expected.Submit(input,expected.Revision);Assert.Equal(ResultCode.Accepted,result.Code);var ready=await s.CaptureSubmit(input,s.Revision).PrepareAsync();var h=new WorldSessionHost(s);Assert.Equal(ResultCode.Accepted,h.CommitSubmit(ready,out var p));Assert.Equal(result,p!.Result);Assert.Equal(Hash(expected),Hash(h.Current));}
}
